session_start();if(!isset($_SESSION['user_id'])||$_SESSION['role']!=='patient'){header('Location: ../auth/login.php');exit();}include('../config/database.php');$user_id=(int)$_SESSION['user_id'];$prescription_id=isset($_GET['id'])?(int)$_GET['id']:0;$q=mysqli_query($conn,"SELECT pr.*,pu.name patient_name,du.name doctor_name,d.name department_name FROM prescriptions pr JOIN patients p ON pr.patient_id=p.id JOIN users pu ON p.user_id=pu.id JOIN doctors dr ON pr.doctor_id=dr.id JOIN users du ON dr.user_id=du.id JOIN departments d ON dr.department_id=d.id WHERE pr.id=$prescription_id AND p.user_id=$user_id LIMIT 1");$pr=mysqli_fetch_assoc($q);if(!$pr)die('Prescription not found.');$items=mysqli_query($conn,"SELECT * FROM prescription_items WHERE prescription_id=$prescription_id ORDER BY id ASC");?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Prescription | ClinicCare</title><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/patient.css"><style>@media print{.print-actions{display:none!important}.print-sheet{border:0!important;box-shadow:none!important;margin:0!important;max-width:none!important}}
</style></head><body><div class="print-actions" style="max-width:800px;margin:20px auto;display:flex;justify-content:space-between;gap:10px"><a href="prescriptions.php" class="patient-secondary-btn">Back</a><button onclick="window.print()" class="patient-primary-btn">Print / Save as PDF</button></div><div class="print-sheet"><div class="prescription-header"><div><h1 style="margin:0;color:var(--cc-navy);font-size:26px">ClinicCare</h1><p style="margin:4px 0;color:var(--cc-muted)">Clinic & Appointment Management System</p></div><div style="text-align:right"><strong>Prescription</strong><div style="font-size:10px;color:var(--cc-muted)"><?php echo date('d M Y',strtotime($pr['created_at']));?></div></div></div><div class="prescription-body"><div class="row"><div class="col-md-6"><p><strong>Patient:</strong> <?php echo htmlspecialchars($pr['patient_name']);?></p></div><div class="col-md-6"><p><strong>Doctor:</strong> Dr. <?php echo htmlspecialchars($pr['doctor_name']);?></p><p><strong>Department:</strong> <?php echo htmlspecialchars($pr['department_name']);?></p></div></div><hr><p><strong>Diagnosis</strong></p><p><?php echo nl2br(htmlspecialchars($pr['diagnosis']));?></p><?php if($pr['notes']){?><p><strong>Notes</strong></p><p><?php echo nl2br(htmlspecialchars($pr['notes']));?></p><?php } ?><h3 style="margin-top:25px;color:var(--cc-navy);font-size:16px">Medicines</h3><?php while($item=mysqli_fetch_assoc($items)){?><div class="medicine-row"><strong><?php echo htmlspecialchars($item['medicine_name']);?></strong><div style="font-size:11px;color:var(--cc-muted);margin-top:4px">Dosage: <?php echo htmlspecialchars($item['dosage']);?> | Duration: <?php echo htmlspecialchars($item['duration']);?></div><div style="font-size:11px;color:var(--cc-muted);margin-top:3px">Instructions: <?php echo htmlspecialchars($item['instructions']);?></div></div><?php } ?><div style="margin-top:50px;text-align:right"><p>____________________________</p><strong>Dr. <?php echo htmlspecialchars($pr['doctor_name']);?></strong></div></div></div></body></html>
